            }
            case LVal.Local local -> equalities.get(local.name());
            case LVal.StaticField sf -> {
                // Handle BigInteger constants: ZERO, ONE, TWO, TEN
                if ("java.math.BigInteger".equals(sf.declaringClass())) {
