                        case "ZERO" -> BigInteger.ZERO;
                        case "ONE" -> BigInteger.ONE;
                        case "TWO" -> BigInteger.valueOf(2);
                        case "TEN" -> BigInteger.TEN;
                        default -> null;
                    };
                }
                yield null;
            }
