            domain.top()
        );

        // Assume x == 10 contradicts x == 5
        var afterAssume = domain.transfer(
            new Step.Assume(new RVal.Binop(
                new LVal.Local("x", "int"),
                BinOp.Eq,
                new RVal.IntConst(BigInteger.valueOf(10))
            )),
            s
        );

        assertTrue(domain.isBottom(afterAssume));
    }

