        var s = domain.transfer(
            new Step.Assign(new LVal.Local("x", "int"), new RVal.IntConst(BigInteger.valueOf(5))),
            domain.top()
        );

        // Assume x == 5 is consistent with x == 5
        var afterAssume = domain.transfer(
