        var atEntry = domain.transfer(
            new Step.Assign(new LVal.Local("x", "int"), new RVal.IntConst(BigInteger.valueOf(5))),
            atAssume
        );

        // At entry, we should have bottom (proven unreachable)
        assertTrue(domain.isBottom(atEntry));
