        assertTrue(domain.entails(s1, s2));
        assertTrue(domain.entails(s2, s1));

        // More specific entails less specific
        var s3 = domain.top();
        assertTrue(domain.entails(s1, s3));
        assertFalse(domain.entails(s3, s1));
    }
